package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.repositories.*;
import com.pet.buscaativa.services.*;

/** Initial recording and P05 use real APIs; only subsequent factual changes use the new command. */
class SpecificCorrectionIndicatorTests extends FrequencyCorrectionTestSupport {
    @Autowired GrupoTerapeuticoService groupService;
    @Autowired SessaoGrupoRepository sessions;
    @BeforeEach void offerToday(){date=LocalDate.now();tx(()->{capacity(professional,date,TurnoEnum.MANHA,10);return null;});}
    private Agendamento reservation(LocalDate day,String time){return tx(()->seed(patient,professional,SituacaoAtendimento.AGENDADO,day,time));}
    private void initial(Agendamento a,String state) throws Exception {var r=mvc.perform(patch("/api/agendamentos/"+a.getId()+"/status").param("novoStatus",state).header("Authorization","Bearer "+tokens.gerarToken(professional))).andReturn().getResponse();assertEquals(200,businessStatus(r),r.getContentAsString());}
    private Agendamento reschedule(Agendamento source,String time) throws Exception {var request=new AgendamentoDTO(null,professional.getIdPublico(),null,patient.getIdPublico(),null,null,date,TurnoEnum.MANHA,LocalTime.parse(time),SituacaoAtendimento.REMARCADO,source.getId(),null);var r=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/agendamentos").header("Authorization","Bearer "+tokens.gerarToken(admin)).contentType("application/json").content(json.writeValueAsString(request))).andReturn().getResponse();assertEquals(201,r.getStatus(),r.getContentAsString());return appointment(json.readTree(r.getContentAsString()).get("id").asLong());}
    private Agendamento[] pair() throws Exception {var original=reservation(date.minusDays(5),"07:00");initial(original,"FALTOU");var second=reschedule(original,"08:00");initial(second,"FALTOU");return new Agendamento[]{appointment(original.getId()),appointment(second.getId())};}
    private void indicators(int n,ClassificacaoRisco risk,boolean visit){var p=patients.findById(patient.getId()).orElseThrow();assertEquals(n,p.getCountFaltas());assertEquals(risk,p.getClassificacaoRisco());assertEquals(visit,p.getGatilhoVisitaAcionado());assertFalse(p.getIndicadoresPendentes());}
    private boolean selected() throws Exception {var r=mvc.perform(get("/api/pacientes/busca-ativa").header("Authorization","Bearer "+tokens.gerarToken(admin))).andReturn().getResponse();assertEquals(200,r.getStatus());return java.util.stream.StreamSupport.stream(json.readTree(r.getContentAsString()).spliterator(),false).anyMatch(n->patient.getIdPublico().toString().equals(n.get("idPublico").asText()));}
    @Test void e01OriginalCorrectionPreservesSubstitutionLinkAndRecalculatesVisit() throws Exception {var p=pair();indicators(2,ClassificacaoRisco.AMARELO,true);long rows=appointments.count(),events=history.count(),count=audits.count();assertEquals(200,correct(p[0]));indicators(1,ClassificacaoRisco.VERDE,false);assertEquals(SituacaoReserva.SUBSTITUIDA,appointment(p[0].getId()).getSituacaoReserva());assertFalse(appointment(p[0].getId()).getOcupaVaga());assertEquals(p[0].getId(),tx(()->appointment(p[1].getId()).getAgendamentoOriginal().getId()));assertTrue(appointment(p[1].getId()).isRemarcacaoAposFalta());assertEquals(date.minusDays(5),patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());assertEquals(rows,appointments.count());assertEquals(events,history.count());assertEquals(count+1,audits.count());assertFalse(selected());}
    @Test void e02ReplacementCorrectionClearsVisitWithoutAddingClinicalFact() throws Exception {var p=pair();long rows=appointments.count(),events=history.count();assertTrue(selected());assertEquals(200,correct(p[1]));indicators(0,ClassificacaoRisco.VERDE,false);assertEquals(date,patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());assertFalse(selected());assertEquals(rows,appointments.count());assertEquals(events,history.count());}
    @Test void e03LaterValidPairSurvivesCorrectionOfEarlierOriginal() throws Exception {var p=pair();var last=reschedule(p[1],"09:00");initial(last,"FALTOU");assertEquals(200,correct(appointment(p[0].getId())));indicators(2,ClassificacaoRisco.AMARELO,true);assertTrue(selected());}
    @Test void e04LaterIndividualPresenceControlsChronologyEvenAfterOlderCorrection() throws Exception {var p=pair();var later=reservation(date,"10:00");initial(later,"PRESENTE");assertEquals(200,correct(p[0]));indicators(0,ClassificacaoRisco.VERDE,false);assertEquals(date,patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());}
    @Test void e04EffectiveLaterGroupPresenceControlsSharedChronology() throws Exception {var p=pair();authenticate();var group=groupService.criarGrupo(new CriarGrupoDTO("Grupo sintético cronologia Etapa 4",professional.getIdPublico(),RecorrenciaGrupo.UNICA,date,null,LocalTime.of(13,0),List.of(patient.getIdPublico())));var session=tx(()->sessions.findAll().stream().filter(x->x.getGrupo().getId().equals(group.id())).findFirst().orElseThrow());var dto=new ConfirmarOcorrenciaGrupoDTO(true,List.of(new FrequenciaParticipanteGrupoDTO(patient.getIdPublico(),StatusPresencaGrupo.PRESENTE)),null,session.getVersion());var r=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/grupos/sessoes/"+session.getId()+"/confirmacao-ocorrencia").header("Authorization","Bearer "+tokens.gerarToken(professional)).contentType("application/json").content(json.writeValueAsString(dto))).andReturn().getResponse();assertEquals(200,r.getStatus());assertEquals(200,correct(p[0]));indicators(0,ClassificacaoRisco.VERDE,false);assertEquals(date,patients.findById(patient.getId()).orElseThrow().getDataUltimaPresenca());}
    @Test void e05ThreeUnrelatedMissesDoNotInventVisit() throws Exception {for(int i=3;i>=1;i--)initial(reservation(date.minusDays(i),"07:00"),"FALTOU");indicators(3,ClassificacaoRisco.VERMELHO,false);assertTrue(selected());}
    @Test void e07SuccessiveEffectiveCorrectionsAreAuditedWithoutDoubleCounting() throws Exception {var p=pair();long rows=appointments.count(),events=history.count(),count=audits.count();var current=p[1];for(var target:List.of(FrequenciaAssistencial.PRESENTE,FrequenciaAssistencial.FALTOU,FrequenciaAssistencial.PRESENTE)){assertEquals(200,correct(professional,current,target,current.getVersion()).getStatus());current=appointment(current.getId());}indicators(0,ClassificacaoRisco.VERDE,false);assertEquals(count+3,audits.count());assertEquals(rows,appointments.count());assertEquals(events,history.count());var before=database();assertEquals(200,correct(professional,current,FrequenciaAssistencial.PRESENTE,current.getVersion()).getStatus());assertEquals(before,database());}
}
